public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Set up a queue to keep track of the n-tersections to explore
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Set up a set to keep track of the visited n-tersections
    Set<int[]> visited = new HashSet<>();

    // Set up a set to keep track of the n-tersections that are reachable from the start n-tersection
    Set<int[]> reachable = new HashSet<>();

    // Iterate through the queue of n-tersections to explore
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        visited.add(current);

        // Check if the current n-tersection is the end n-tersection
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // For each adjacent n-tersection that has not been visited, add it to the queue and mark it as reachable
        for (int[] neighbor : paths[current[0]][current[1]]) {
            if (!visited.contains(neighbor) && !reachable.contains(neighbor)) {
                queue.add(neighbor);
                reachable.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

