public double trimMean(int[] arr) {
    // Calculate the mean of the array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the 5% cutoff points
    double min_cutoff = mean - 0.05 * mean;
    double max_cutoff = mean + 0.05 * mean;

    // Remove the smallest 5% and largest 5% values
    int num_removed = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < min_cutoff || arr[i] > max_cutoff) {
            num_removed++;
            arr[i] = Integer.MAX_VALUE;
        }
    }

    // Recalculate the mean of the remaining values
    double new_mean = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != Integer.MAX_VALUE) {
            new_mean += arr[i];
        }
    }
    new_mean /= arr.length - num_removed;

    return new_mean;
}

public static double trimMean(int[] arr) {
    int n = arr.length;
    int trim = (int) Math.round(n * 0.05);
    int trimmedN = n - trim * 2;
    int[] trimmedArr = new int[trimmedN];
    for (int i = trim; i < n - trim; i++) {
        trimmedArr[i-trim] = arr[i];
    }
    double mean = 0.0;
    for (int i : trimmedArr) {
        mean += i;
    }
    return mean / trimmedN;
}

