    }

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the number of elements to remove from the beginning and end
    int removeBegin = (int) Math.round(arr.length * 0.05);
    int removeEnd = (int) Math.round(arr.length * 0.05);

    // Remove the elements from the beginning and end
    for (int i = 0; i < removeBegin; i++) {
        arr = Arrays.copyOfRange(arr, removeBegin, arr.length - removeEnd);
    }

    // Calculate the mean of the remaining elements
    double sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    double mean = sum / arr.length;

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000.0;
}

