public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time to 0
    int minTime = 0;
    // Initialize a boolean array to keep track of the visited nodes
    boolean[] visited = new boolean[n];
    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    // Mark the root node as visited and add it to the queue
    visited[0] = true;
    queue.add(0);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int node = queue.poll();
        // Loop through the neighbors of the current node
        for (int neighbor : edges[node]) {
            // If the neighbor has an apple and has not been visited, update the minimum time
            if (hasApple[neighbor] && !visited[neighbor]) {
                minTime += 2;
            }
            // Mark the neighbor as visited and add it to the queue
            visited[neighbor] = true;
            queue.add(neighbor);
        }
    }
    // Return the minimum time
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    int minTime = 0;
    boolean[] visited = new boolean[n];
    visited[0] = true;

    for (int i = 1; i < n; i++) {
        dist[i] = Integer.MAX_VALUE;
    }

    for (int i = 1; i < n; i++) {
        if (!visited[i]) {
            int minDist = Integer.MAX_VALUE;
            int minNode = -1;
            for (int j = 0; j < n; j++) {
                if (edges[i][j] != 0 && !visited[j]) {
                    minDist = Math.min(minDist, dist[j] + edges[i][j]);
                    minNode = j;
                }
            }
            dist[i] = minDist;
            visited[i] = true;
            minTime += minDist;
            if (hasApple[i]) {
                minTime += 2;
            }
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D matrix to store the minimum time required to collect all apples
    int[][] dp = new int[n][n];

    // Initialize the first row of the matrix with the number of apples in each node
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            dp[i][i] = 1;
        }
    }

    // Fill in the rest of the matrix using the minimum time required to collect all apples
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int minTime = Integer.MAX_VALUE;
            for (int k = 0; k < n; k++) {
                if (hasApple[k] && dp[i][k] != 0) {
                    minTime = Math.min(minTime, dp[i][k] + 1);
                }
            }
            dp[i][j] = minTime;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return dp[0][n-1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // create a 2D array to represent the graph
    int[][] graph = new int[n][n];
    for (int i = 0; i < edges.length; i++) {
        int from = edges[i][0];
        int to = edges[i][1];
        graph[from][to] = 1;
        graph[to][from] = 1;
    }

    // initialize the minimum time to 0
    int minTime = 0;

    // create a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // perform BFS until the queue is empty
    while (!queue.isEmpty()) {
        // get the current node from the queue
        int node = queue.poll();

        // if the current node has an apple, update the minimum time
        if (hasApple[node]) {
            minTime = Math.max(minTime, graph[0][node]);
        }

        // add the neighbor nodes to the queue
        for (int neighbor : graph[node]) {
            if (neighbor != -1 && !queue.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    int[] parent = new int[n];
    int[] time = new int[n];

    // Initialize the distance and parent arrays
    for (int i = 0; i < n; i++) {
        distance[i] = Integer.MAX_VALUE;
        parent[i] = -1;
        time[i] = 0;
    }

    // Perform a Breadth-First Search to find the shortest path to each node
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            int currentTime = time[i];
            int currentNode = i;
            while (currentNode != 0) {
                currentTime += distance[currentNode];
                currentNode = parent[currentNode];
            }
            if (currentTime < time[0]) {
                time[0] = currentTime;
            }
        }
    }

    return time[0];
}

public String sortString(String s) {
    // Step 1: Pick the smallest character from s and append it to the result.
    int smallestIndex = findSmallestIndex(s);
    String result = s.substring(smallestIndex, smallestIndex + 1);

    // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
    int nextSmallestIndex = findNextSmallestIndex(s, smallestIndex + 1);
    String nextSmallest = s.substring(nextSmallestIndex, nextSmallestIndex + 1);
    result = result + nextSmallest;

    // Step 3: Repeat step 2 until you cannot pick more characters.
    while (nextSmallestIndex < s.length()) {
        smallestIndex = nextSmallestIndex;
        smallest = nextSmallest;
        nextSmallestIndex = findNextSmallestIndex(s, smallestIndex + 1);
        nextSmallest = s.substring(nextSmallestIndex, nextSmallestIndex + 1);
        result = result + smallest + nextSmallest;
    }

    // Step 4: Pick the largest character from s and append it to the result.
    int largestIndex = findLargestIndex(s);
    String largest = s.substring(largestIndex, largestIndex + 1);
    result = result + largest;

    // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
    int previousLargestIndex = findPreviousLargestIndex(s, largestIndex - 1);
    String previousLargest = s.substring(previousLargestIndex, previousLargestIndex + 1);
    result = result + previousLargest;

    // Step 6: Repeat step 5 until you cannot pick more characters.
    while (previousLargestIndex > 0) {
        largestIndex = previousLargestIndex;
        largest = previousLargest;
        previousLargestIndex = findPreviousLargestIndex(s, largestIndex - 1);
        previousLargest = s.substring(previousLargestIndex, previousLargestIndex + 1);
        result = result + largest + previousLargest;
    }

    // Step 7: Repeat the steps from 1 to 6 until you pick all characters from s.
    while (result.length() < s.length()) {
        smallestIndex = findSmallestIndex(s);
        smallest = s.substring(smallestIndex, smallestIndex + 1);
        result = result + smallest;
        nextSmallestIndex = findNextSmallestIndex(s, smallestIndex + 1);
        nextSmallest = s.substring(nextSmallestIndex, nextSmallestIndex + 1);
        result = result + nextSmallest;
        largestIndex = findLargestIndex(s);
        largest = s.substring(largestIndex, largestIndex + 1);
        result = result + largest;
        previousLargestIndex = findPreviousLargestIndex(s, largestIndex - 1);
        previousLargest = s.substring(previousLargestIndex, previousLargestIndex + 1);
        result = result + previousLargest;
    }

    return result;
}

public String sortString(String s) {
    // Initialize result string
    String result = "";

    // Loop until all characters are picked
    while (s.length() > 0) {
        // Find the smallest character in s
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(smallestIndex)) {
                smallestIndex = i;
            }
        }

        // Append the smallest character to the result
        result += s.charAt(smallestIndex);

        // Remove the smallest character from s
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
    }

    // Reverse the result to get the final sorted string
    result = new StringBuilder(result).reverse().toString();

    return result;
}

