public String sortString(String s) {
    // Formats the input string
    String sortedString = "";
    String alphabet = "abcdefghijklmnopqrstuvwxyz";
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int position = alphabet.indexOf(c);
        if (position == -1) {
            // Ignore any non-alphabet characters
            continue;
        }
        // Add the character to the result string
        if (sortedString.length() == 0) {
            sortedString = "" + c;
        } else {
            sortedString = sortedString.substring(0, sortedString.length() - 1) + c;
        }
        // If the character is the last one in the alphabet, break
        if (position == alphabet.lastIndexOf(c)) {
            break;
        }
    }
    return sortedString;
}

