        // If the smallest character appears multiple times in s, pick any occurrence
        if (s.contains(smallest)) {
            char otherSmallest = getSmallestChar(s.substring(s.indexOf(smallest) + 1));
            result.append(otherSmallest);
            s = removeChar(s, otherSmallest);
        }
    }

    // Append the largest character of s to the result
    result.append(getLargestChar(s));

    // Return the sorted string
    return result.toString();
}

