public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
        int minCost = Integer.MAX_VALUE;
        for (int i = 0; i < cost.length; i++) {
            int currentCost = cost[i];
            if (i == 0) {
                minCost = currentCost;
            } else {
                minCost = Math.min(minCost, currentCost + cost[i - 1]);
            }
        }
        return minCost;
    }

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return cost[0];
    } else {
        int[] dp = new int[n];
        dp[0] = cost[0];
        dp[1] = Math.min(cost[0], cost[1]);
        for (int i = 2; i < n; i++) {
            dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
        }
        return Math.min(dp[n-1], dp[n-2]);
    }
}

