    // Create a string containing the Morse code characters for the letters
    String morseCodes = ".-,-...,-.-.,-..,.,..-.,--.,....,.....,----,....,-.-.-,-...-,-.--,-....-,--...-,-....--,---..,--.--.,-.-.--,---...,.-..-.,...-.--,....-,...-.--.-,-..-.-,..--.-,--..--,--...--,---..-,-.-..-,.-.-..,..---..,-----.,----.,----.-,-----.,--...-.,-.--.-,-....-,..---,..-..-,.-...,-...-,....-,-..-.,--...,--..-,---.,-.---,-...-,--..-,.----,..---,...--,-..-.,...-,.--.-,-.--,---,.-.-.-,-.-..,..-..-,-.--,-.--.,-....,.-.-.,-.--.-,-...-,-.--,-..-,-....-,...-.,.--.-,-.-.,...-,.--.--,-.,--,--.-,.-..-,-.--.,-.--.",

    // Get the Morse code for each letter in the alphabet
    for (int i = 0; i < 26; i++) {
