            if (c >= 'a' && c <= 'z') {
                // Convert the character to its uppercase version
                c = (char)(c - 'a' + 'A');
            }
            // Get the Morse code for the character
            morseWords[i][j] = morseTable[c - 'A'];
        }
    }

    // Step 3: Count the number of unique Morse code representations
    Set<String> seen = new HashSet<>();
    int unique = 0;
    for (String word : morseWords) {
        String m = "";
        for (String s : word) {
            m += s;
        }
        if (!seen.contains(m)) {
            unique++;
            seen.add(m);
        }
    }

    return unique;
}

