int leftParenCount = s.length() - s.replace("(", "").length();
int rightParenCount = s.length() - s.replace(")", "").length();

// If the number of left and right parentheses are not equal,
// we need to insert parentheses to make them balanced
if(leftParenCount != rightParenCount) {
insertions = Math.abs(leftParenCount - rightParenCount);
}

// Loop through the string and insert parentheses as needed
for(int i = 0; i < s.length(); i++) {
if(s.charAt(i) == '(') {
balanceString += s.charAt(i);
}
if(s.charAt(i) == ')') {
balanceString += balanceString.length() > 0 ? balanceString.charAt(balanceString.length() - 1) : s.charAt(i);
}

return insertions;
}

