public int minOperations(int n) {
    int minOperations = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int maxValue = arr[0];
    for (int i = 1; i < n; i++) {
        maxValue = Math.max(maxValue, arr[i]);
    }
    while (maxValue > 0) {
        int x = -1;
        int y = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] == maxValue) {
                x = i;
                break;
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (arr[i] == maxValue) {
                y = i;
                break;
            }
        }
        arr[x] -= 1;
        arr[y] += 1;
        maxValue--;
        minOperations++;
    }
    return minOperations;
}

