public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    char[] chars = s.toCharArray();
    for (int i = 0; i < chars.length - 1; i++) {
        if (chars[i] != chars[i + 1] && Character.isLowerCase(chars[i]) != Character.isLowerCase(chars[i + 1])) {
            chars[i] = ' ';
            chars[i + 1] = ' ';
        }
    }
    return new String(chars).replaceAll("\\s+", "");
}

public String makeGood(String s) {
