    StringBuilder result = new StringBuilder();

    for (int i = 0; i < charArray.length - 1; i++) {
        char curr = charArray[i];
        char next = charArray[i + 1];

        if (Character.isLowerCase(curr) && Character.isLowerCase(next) && Math.abs(curr - next) == 32) {
            continue;
        } else if (Character.isUpperCase(curr) && Character.isLowerCase(next) && Math.abs(curr - next) == 32) {
            continue;
        }

        result.append(curr);
    }

    if (!result.toString().equals("")) {
        result.append(charArray[charArray.length - 1]);
    }

    return result.toString();
}

