public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    int currentValue = 0;
    int currentIndex = 0;

    while (currentValue < k) {
        chars[currentIndex++] = 'a';
        currentValue++;
    }

    for (int i = currentIndex - 1; i >= 0; i--) {
        chars[i] = (char) ('a' + (k - currentValue));
        currentValue -= (k - currentValue);
    }

    return new String(chars);
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive");
    }
    if (n == 1) {
        return Character.toString((char) ('a' + k - 1));
    }
    String smallestString = "";
    int remainingValue = k;
    for (int i = n - 1; i >= 0; i--) {
        int charValue = Math.min(remainingValue, 26);
        smallestString += Character.toString((char) ('a' + charValue - 1));
        remainingValue -= charValue;
    }
    return smallestString;
}

