public static int[] diagonalOrder(int[][] mat) {

    Objects.requireNonNull(mat);
    ArrayList<Integer> result = new ArrayList<>();
    int i = 0, j = 0;

    while (i < mat.length - 1 && i >= 0 && j < mat[i].length - 1 && j >= 0) {

        result.add(mat[i][j]);

        // move to next element in the diagonal
        if (i == j) {
            if (i == mat.length - 1) {
                j++;
            } else if (j == mat[i].length - 1) {
                i++;
            } else {
                i++;
                j++;
            }
        } else {
            if (i == 0) {
                j++;
            } else if (j == 0) {
                i++;
            } else {
                i--;
                j--;
            }
        }
    }

    // make sure the rest elements are added to the result
    while (i < mat.length && j < mat[i].length) {
        result.add(mat[i][j]);
        i++;
        j++;
    }

    return result.toArray();
}

