    int n = mat.length;
    if (n == 0) {
        return new int[0];
    }

    // Create a list to store the diagonal elements
    List<Integer> diagonal = new ArrayList<>();

    // Iterate through each row
    for (int i = 0; i < n; i++) {
        // Iterate through each column
        for (int j = 0; j < n - i; j++) {
            // Add the diagonal element to the list
            diagonal.add(mat[i][j]);
        }
    }

    // Convert the list to an array and return it
    return diagonal.toArray(new int[0]);
}

public static int findSmallestInteger(int n) {
  List<String> digitList = new ArrayList<>();
  while (n > 0) {
    int digit = n % 10;
    digitList.add(String.valueOf(digit));
    n = n / 10;
  }
  Collections.sort(digitList);
  String sortedDigits = String.join("", digitList);
  int smallestInteger = Integer.parseInt(sortedDigits);
  if (smallestInteger > n) {
    return smallestInteger;
  } else {
    return -1;
  }
}

public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }
    Collections.sort(digits);
    int result = 0;
    for (int i = digits.size() - 1; i >= 0; i--) {
        result = result * 10 + digits.get(i);
    }
    return result;
}

