public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    int a1 = x2 - x1;
    int b1 = y2 - y1;
    int a2 = x3 - x1;
    int b2 = y3 - y1;
    return a1 * b2 == a2 * b1;
}

public static boolean isBoomerang(int[][] points) {
    if(points.length < 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    if(x1 == x2 && x2 == x3) {
        return false;
    }
    if(y1 == y2 && y2 == y3) {
        return false;
    }

    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) == 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    // Create a set of unique points
    Set<String> uniquePoints = new HashSet<>();
    for (int[] point : points) {
        uniquePoints.add(point[0] + "," + point[1]);
    }

    // Check if there are any repeated points
    if (uniquePoints.size() != 3) {
        return false;
    }

    // Check if the slopes of the lines connecting the points are all different
    int[] slopes = new int[3];
    for (int i = 0; i < 3; i++) {
        int j = (i + 1) % 3;
        slopes[i] = (points[j][1] - points[i][1]) / (points[j][0] - points[i][0]);
    }

    return slopes[0] != slopes[1] && slopes[1] != slopes[2] && slopes[2] != slopes[0];
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Check if points are not collinear
    if (((p2[0] - p1[0]) * (p3[1] - p1[1])) == ((p2[1] - p1[1]) * (p3[0] - p1[0]))) {
        return false;
    }

    // Check if points form a triangle
    if (Math.abs((p2[0] - p1[0]) * (p3[1] - p1[1])) != Math.abs((p2[1] - p1[1]) * (p3[0] - p1[0]))) {
        return false;
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    // Get the slopes of the three segments
    double slope1 = (double) (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (double) (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);
    double slope3 = (double) (points[0][1] - points[2][1]) / (points[0][0] - points[2][0]);

    // Check if the slopes are all equal
    return (slope1 == slope2 && slope2 == slope3);
}

