public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // Check if i is a perfect square
        if (i * i == n) {
            // If it is, add it to the list
            perfectSquares.add(i);
        }
    }

    // Return the length of the list
    return perfectSquares.size();
}

public static int minPerfectSquareSum(int n) {
    int minSum = n;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int j = n - i * i;
        if (j == 0) {
            return 1;
        } else {
            minSum = Math.min(minSum, minPerfectSquareSum(j) + 1);
        }
    }
    return minSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i * i;
        if (sum == n) {
            count++;
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int sqrt = (int) Math.sqrt(n);
        if (sqrt * sqrt == n) {
            minSquares = 1;
            break;
        } else if (sqrt * Math.sqrt(n - sqrt) == n) {
            minSquares = 2;
            break;
        }
    }
    return minSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
        sb.append(reverse(word));
        sb.append(" ");
    }
    return sb.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] chars = words[i].toCharArray();
        for (int j = 0; j < chars.length / 2; j++) {
            char temp = chars[j];
            chars[j] = chars[chars.length - j - 1];
            chars[chars.length - j - 1] = temp;
        }
        words[i] = new String(chars);
    }
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder output = new StringBuilder();
    for (String word : words) {
        output.append(new StringBuilder(word).reverse().toString());
    }
    return output.toString();
}

